ALTER TABLE ai_workflows
    DROP COLUMN IF EXISTS tag,
    DROP COLUMN IF EXISTS deleted_at,
    DROP COLUMN IF EXISTS status;

DROP INDEX IF EXISTS idx_log_entry_workflow_id;
