ALTER TABLE log_entry
    DROP COLUMN IF EXISTS request_sla,
    DROP COLUMN IF EXISTS workflow_step_id,
    DROP COLUMN IF EXISTS workflow_id,
    DROP COLUMN IF EXISTS workflow_tag;
